SELECT ip.id AS inspectParameterId, ip.name AS inspectParameterName, ip.code AS inspectParameterCode, t.record_id AS recordId, t.record_version_id AS recordVersionId, br.name AS recordName, br.code AS recordCode, brv.version AS recordVersionNo FROM lm_task t INNER JOIN lm_inspect_parameter ip ON ip.id = t.parameter_id INNER JOIN lm_inspection_order io ON io.id = t.inspection_order_id INNER JOIN lm_inspect_item ii ON ii.id = t.inspect_item_id LEFT JOIN bm_batch_record br ON br.id = t.record_id AND br.is_deleted = 0 LEFT JOIN bm_batch_record_version brv ON brv.id = t.record_version_id AND brv.is_deleted = 0 WHERE t.is_deleted = 0 AND ip.is_deleted = 0 AND ii.is_deleted = 0 AND io.is_deleted = 0
AND t.execute_method = #{query.executeMethod}
AND t.parameter_id = #{query.parameterId}
AND t.parameter_id IN
#{pid}
AND t.status = 'TO_REVIEW'
AND t.status NOT IN ('PENDING_ASSIGNMENT','RETURN_PENDING_APPROVAL')
AND t.owner_id = #{query.currentUserId}
AND t.parameter_id = #{query.parameterId}
AND t.parameter_id IN
#{pid}
AND ii.name LIKE CONCAT('%', #{query.inspectItemName}, '%')
AND ip.name LIKE CONCAT('%', #{query.parameterName}, '%')
AND io.order_no LIKE CONCAT('%', #{query.inspectionOrderNo}, '%')
AND io.batch_no LIKE CONCAT('%', #{query.batchNo}, '%')
AND io.create_time >= #{query.requestStartTime}
AND io.create_time <= #{query.requestEndTime}
AND io.material_id IN
#{materialId}
AND t.status IN
#{st}
AND ((t.judged_abnormal = 1 AND t.status != 'TERMINATED') OR t.status IN ('REVIEW_REJECTED','SAMPLE_AUDIT_REJECTED'))
AND t.judged_abnormal = 0
GROUP BY ip.id, ip.name, ip.code, t.record_id, t.record_version_id, br.name, br.code, brv.version ORDER BY ii.code ASC, ip.code ASC, recordCode ASC, recordVersionNo ASC

SELECT io.id as inspectionOrderId, io.order_no, io.batch_no, io.create_time as requestTime, io.create_by as requestUserId, m.name as materialName, m.code as materialCode, m.specification as materialSpec FROM lm_inspection_order io INNER JOIN lm_task t ON io.id = t.inspection_order_id LEFT JOIN lm_inspect_material m ON io.material_id = m.id WHERE io.is_deleted = 0 AND t.is_deleted = 0
