AND t.inspect_item_id = #{inspectItemId}
AND t.record_version_id = #{recordVersionId}
AND t.execute_method = #{query.executeMethod}
AND t.status = 'TO_REVIEW'
AND t.status NOT IN ('PENDING_ASSIGNMENT','RETURN_PENDING_APPROVAL')
AND t.owner_id = #{query.currentUserId}
AND ii.name LIKE CONCAT('%', #{query.inspectItemName}, '%')
AND io.order_no LIKE CONCAT('%', #{query.inspectionOrderNo}, '%')
AND io.batch_no LIKE CONCAT('%', #{query.batchNo}, '%')
AND io.create_time >= #{query.requestStartTime}
AND io.create_time <= #{query.requestEndTime}
AND io.material_id IN
#{materialId}
AND t.status IN
#{st}
AND ((t.judged_abnormal = 1 AND t.status != 'TERMINATED') OR t.status IN ('REVIEW_REJECTED','SAMPLE_AUDIT_REJECTED'))
AND t.judged_abnormal = 0
ORDER BY io.create_time ASC, io.order_no ASC

